void BfmeListVMU::bfmeEraseVMU(BfmeNodeVMU **it)
{
	BfmeNodeVMU *target = *it;
	BfmeNodeVMU *head = mpHead;

	if (target == head)
	{
		if (head != 0)
		{
			BfmeNodeVMU *next = head->mpNext;
			((AptSharedHandle *)head)->detach(); // the node's first word is the shared handle (0x006CD530)
			g_pDogmaPoolManager->freeBlock(head, 8);
			mpHead = next;
		}
		return;
	}
	BfmeNodeVMU *prev = mpHead;
	while (prev != 0)
	{
		if (prev->mpNext == target)
			break;
		prev = prev->mpNext;
	}
	BfmeNodeVMU *node = prev->mpNext;
	if (node != 0)
	{
		prev->mpNext = node->mpNext;
		((AptSharedHandle *)node)->detach();
		g_pDogmaPoolManager->freeBlock(node, 8);
	}
}

